// Extract reminders and follow-up tasks array from Django response
const res = $input.item.json;
const appointments = Array.isArray(res) ? res : (res.reminders || res.appointments || []);
const followUps = res.follow_ups || [];

const items = [];

for (const appt of appointments) {
  items.push({
    json: {
      type: '24h_pre_visit',
      appointment_id: appt.appointment_id || appt.id,
      patient_name: appt.patient_name || 'Patient',
      patient_phone: appt.patient_phone || appt.phone,
      telegram_chat_id: appt.telegram_chat_id,
      doctor_name: appt.doctor_name || (appt.doctor && appt.doctor.name) || 'Attending Physician',
      service_name: appt.service_name || (appt.service && appt.service.name) || 'Consultation',
      start_datetime: appt.start_datetime,
      time_display: appt.time_display || new Date(appt.start_datetime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      date_display: appt.date_display || new Date(appt.start_datetime).toLocaleDateString([], { weekday: 'long', month: 'short', day: 'numeric' })
    }
  });
}

for (const task of followUps) {
  items.push({
    json: {
      type: 'doctor_followup_recall',
      task_id: task.id,
      appointment_id: task.appointment_id,
      patient_name: task.patient_name || 'Patient',
      patient_phone: task.patient_phone,
      telegram_chat_id: task.telegram_chat_id,
      doctor_name: task.doctor_name || 'Doctor',
      clinical_notes: task.notes || 'Recommended follow-up visit',
      due_date: task.follow_up_date
    }
  });
}

return items.length > 0 ? items : [{ json: { type: 'none_pending', checked_at: new Date().toISOString() } }];

